SourceCode.Declaration:
/// <summary>
/// The session service's request: the company, the signed-in worker, this device, and the worker's unfinished
/// work on this device (jobs not yet registered, counts not yet submitted) - reported with every check.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSessionRequest
{
    str         dataAreaId;
    str         userName;
    str         deviceId;
    int         pendingJobs;
    int         pendingCounts;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public str parmDataAreaId(str _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('PendingJobs')]
public int parmPendingJobs(int _value = pendingJobs)
{
    pendingJobs = _value;
    return pendingJobs;
}

[DataMemberAttribute('PendingCounts')]
public int parmPendingCounts(int _value = pendingCounts)
{
    pendingCounts = _value;
    return pendingCounts;
}
